    General_Info = apps.get_model('eval', 'General_Info')
    Evaluation = apps.get_model('eval', 'Evaluation')
    EvaluationScore = apps.get_model('eval', 'EvaluationScore')
    groups = {}
    for row in General_Info.objects.order_by('id'):
        key = (row.teacher_name, row.upload_date, row.assessor, row.topic, row.sub_topic)
        groups.setdefault(key, []).append(row)
    for rows in groups.values():
        first = rows[0]
        evaluation = Evaluation.objects.create(
            teacher_name=first.teacher_name or '(name not recorded)', student_class_id=first.classs_id,
            subject_id=first.subject_id, topic=first.topic, sub_topic=first.sub_topic,
            general_comment=first.general_comment, assessor=first.assessor, date=first.upload_date)
        seen = set()
        for row in rows:
            if row.questions_items_id and row.questions_items_id not in seen:
                seen.add(row.questions_items_id)
                EvaluationScore.objects.create(evaluation=evaluation, question_id=row.questions_items_id,
                                               score=row.score)


